package main

import (
	"encoding/hex"
	"encoding/json"
	"math/rand"
	"os"
	"testing"

	"github.com/vmihailenco/msgpack/v5"
)

// The optional corpus is generated by protocol/verify_reference.cjs from the
// pinned public client's pure in-memory text engine. Default tests neither
// download vendor code nor read any account or thread data.
func TestNativeTextReferenceCorpus(t *testing.T) {
	path := os.Getenv("CAOS_DELTA_TEXT_REFERENCE_CASES")
	if path == "" {
		t.Skip("set CAOS_DELTA_TEXT_REFERENCE_CASES to an explicitly generated corpus")
	}
	var corpus struct {
		Build string
		Cases []struct {
			Name  string
			Steps []struct {
				Timestamp uint64
				Actor     byte
				Parents   []int
				Wire      string
			}
			Heads    []int
			Expected string
			Anchors  []struct {
				Step     int
				Offset   uint64
				Right    bool
				Expected *int
			}
		}
	}
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	if err := json.Unmarshal(data, &corpus); err != nil {
		t.Fatal(err)
	}
	if corpus.Build != "45918daa2b408d0f2efa573d44165d038c0d3109" || len(corpus.Cases) != 128 {
		t.Fatal("unexpected native reference build or case count")
	}
	for _, test := range corpus.Cases {
		t.Run(test.Name, func(t *testing.T) {
			var batches []historyDeltaBatch
			for _, step := range test.Steps {
				wire, err := hex.DecodeString(step.Wire)
				if err != nil {
					t.Fatal(err)
				}
				payload := replayPayload(t, 2, []any{1, []byte{0}}, msgpack.RawMessage(wire))
				batch := historyDeltaBatch{ID: replayID(step.Timestamp, step.Actor), Payloads: []wireVariant{payload}}
				for _, parent := range step.Parents {
					if parent < 0 || parent >= len(batches) {
						t.Fatal("invalid native corpus parent")
					}
					batch.Parent = append(batch.Parent, batches[parent].ID)
				}
				batches = append(batches, batch)
			}
			var heads []deltaID
			for _, head := range test.Heads {
				if head < 0 || head >= len(batches) {
					t.Fatal("invalid native corpus head")
				}
				heads = append(heads, batches[head].ID)
			}
			random := rand.New(rand.NewSource(19))
			for iteration := 0; iteration < 5; iteration++ {
				random.Shuffle(len(batches), func(i, j int) { batches[i], batches[j] = batches[j], batches[i] })
				state, err := replayHistory(batches, heads)
				if err != nil {
					t.Fatal(err)
				}
				if actual := state.Buffers[fieldObject(0)].stringAt(state.basis); actual != test.Expected {
					t.Fatalf("Go text %q differs from native text %q", actual, test.Expected)
				}
				for _, query := range test.Anchors {
					if query.Step < 0 || query.Step >= len(test.Steps) {
						t.Fatal("invalid native anchor step")
					}
					step := test.Steps[query.Step]
					anchor := scratchAnchor{
						Kind: 2, Buffer: fieldObject(0), Insertion: replayID(step.Timestamp, step.Actor),
						Offset: query.Offset, RightBias: query.Right,
					}
					actual, err := state.resolveAnchor(anchor)
					if query.Expected == nil {
						if err == nil {
							t.Fatal("Go resolved an anchor absent from the native snapshot")
						}
					} else if err != nil || actual != *query.Expected {
						t.Fatalf("Go anchor %d %v differs from native %d", actual, err, *query.Expected)
					}
				}
			}
		})
	}
}
